mapper.select:
SELECT T.CONTENT_ID, T.CONTENT_TYPE_ID, T.CATEGORY_ID, C.NAME AS CATEGORY_NAME, T.TITLE AS TITLE, T.FIRST_IMAGE AS FIRST_IMAGE, T.FIRST_IMAGE2 AS FIRST_IMAGE2, T.ADDR1 AS ADDR1, T.ADDR2 AS ADDR2, T.MAP_X, T.MAP_Y, T.L_DONG_SIGNGU_CD, L.L_DONG_SIGNGU_NM AS L_DONG_SIGNGU_NM, T.VIEW_COUNT, COUNT(F.FAVORITE_ID) AS FAV_COUNT, COUNT(F.FAVORITE_ID) AS FAVORITE_COUNT, MAX(CASE WHEN F2.USER_ID = #{userId} THEN 'Y' ELSE 'N' END) AS LIKED_YN, COUNT(R.REVIEW_ID) AS REVIEW_COUNT FROM TOUR_PLACE T LEFT JOIN CATEGORY C ON T.CATEGORY_ID = C.ID LEFT JOIN LDONG L ON T.L_DONG_SIGNGU_CD = L.L_DONG_SIGNGU_CD LEFT JOIN FAVORITE F ON T.CONTENT_ID = F.CONTENT_ID LEFT JOIN FAVORITE F2 ON T.CONTENT_ID = F2.CONTENT_ID AND F2.USER_ID = #{userId} LEFT JOIN REVIEW R ON T.CONTENT_ID = R.CONTENT_ID AND R.REVIEW_ACTIVE = 'Y'
GROUP BY T.CONTENT_ID, T.CONTENT_TYPE_ID, T.CATEGORY_ID, C.NAME, T.TITLE, T.FIRST_IMAGE, T.FIRST_IMAGE2, T.ADDR1, T.ADDR2, T.MAP_X, T.MAP_Y, T.L_DONG_SIGNGU_CD, L.L_DONG_SIGNGU_NM, T.VIEW_COUNT
LIMIT #{offset}, #{limit}

mapper.update:
UPDATE TOUR_PLACE
SET VIEW_COUNT = IFNULL(VIEW_COUNT, 0) + 1
WHERE CONTENT_ID = #{contentId}

mapper.select:
SELECT COUNT(*)
FROM FAVORITE
WHERE CONTENT_ID = #{contentId}
  AND USER_ID    = #{userId}

mapper.delete:
DELETE FROM FAVORITE
WHERE CONTENT_ID = #{contentId}
  AND USER_ID    = #{userId}
